
(()=>{"use strict";
if(document.getElementById('u6006-nav'))return;
const sections=[['home','/','⌂'],['codes','/fehlercodes/','▣'],['tech','/technik/','⚙'],['repair','/reparatur-wartung/','🔧'],['vehicle','/fahrzeug/','▱']];
const words={tr:{home:'Ana Sayfa',codes:'Kodlar',tech:'Teknik',repair:'Bakım',vehicle:'Araç',search:'Sitede ara',go:'Ara',all:'Tüm kodları aç',hint:'Kod, sistem veya parça ara: DPF, ABS, P0299…',last:'Son görüntülenenler',busy:'Katalog yükleniyor…',empty:'Sonuç bulunamadı.'},de:{home:'Start',codes:'Codes',tech:'Technik',repair:'Wartung',vehicle:'Fahrzeug',search:'Website durchsuchen',go:'Suchen',all:'Alle Codes',hint:'Code, System oder Teil suchen: DPF, ABS, P0299…',last:'Zuletzt geöffnet',busy:'Katalog wird geladen…',empty:'Keine Treffer.'},en:{home:'Home',codes:'Codes',tech:'Technical',repair:'Service',vehicle:'Vehicle',search:'Search the site',go:'Search',all:'All codes',hint:'Search code, system or part: DPF, ABS, P0299…',last:'Recently viewed',busy:'Loading catalog…',empty:'No matches.'}};
function language(){let l='';try{l=localStorage.getItem('6006-language')||''}catch(e){}const h=document.documentElement.lang.slice(0,2).toLowerCase();return words[l]?l:words[h]?h:words[(navigator.language||'tr').slice(0,2)]?(navigator.language||'tr').slice(0,2):'tr'}
const txt=k=>words[language()][k],mk=(tag,cls)=>{const e=document.createElement(tag);if(cls)e.className=cls;return e};
const active=location.pathname.includes('fehlercodes')?'codes':location.pathname.includes('technik')?'tech':location.pathname.includes('reparatur-wartung')?'repair':location.pathname.includes('fahrzeug')?'vehicle':'home';
const nav=mk('nav');nav.id='u6006-nav';nav.setAttribute('aria-label','6006 Navigation');
for(const [key,url,icon]of sections){const a=mk('a');a.href=url;a.dataset.nav=key;a.innerHTML='<span aria-hidden="true">'+icon+'</span><span>'+txt(key)+'</span>';if(key===active){a.classList.add('current');a.setAttribute('aria-current','page')}nav.append(a)}document.body.append(nav);
const tools=mk('div');tools.id='u6006-tools';
const openBtn=mk('button','u6006-fab');openBtn.type='button';openBtn.textContent='⌕';openBtn.setAttribute('aria-label',txt('search'));tools.append(openBtn);
const topBtn=mk('button','u6006-fab');topBtn.type='button';topBtn.textContent='↑';topBtn.setAttribute('aria-label','Scroll to top');topBtn.hidden=true;topBtn.onclick=()=>window.scrollTo({top:0,behavior:'smooth'});tools.append(topBtn);
document.body.append(tools);addEventListener('scroll',()=>topBtn.hidden=window.scrollY<400,{passive:true});
const overlay=mk('div');overlay.id='u6006-search';overlay.hidden=true;overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');
overlay.innerHTML='<div class="u6006-modal"><div class="u6006-modal-head"><strong id="u6006-title"></strong><button class="u6006-close" aria-label="Close" type="button">×</button></div><form class="u6006-query-form"><input type="search" id="u6006-q" enterkeyhint="search" autocomplete="off" aria-label="Search fault code"/><button type="submit" id="u6006-go"></button></form><p class="u6006-help" id="u6006-hint"></p><div id="u6006-results" class="u6006-quick-results" aria-live="polite"></div><div class="u6006-shortcuts"><a href="/fehlercodes/?category=turbo">Turbo</a><a href="/fehlercodes/?category=dpf">DPF</a><a href="/fehlercodes/?category=adblue">AdBlue</a><a href="/fehlercodes/?category=brake">ABS</a><a href="/fehlercodes/?category=network">CAN</a><a href="/fehlercodes/" id="u6006-all"></a></div></div>';
document.body.append(overlay);
const get=id=>document.getElementById(id),input=get('u6006-q'),results=get('u6006-results');
const applyLabels=()=>{nav.querySelectorAll('a').forEach(a=>a.lastElementChild.textContent=txt(a.dataset.nav));get('u6006-title').textContent=txt('search');get('u6006-go').textContent=txt('go');get('u6006-hint').textContent=txt('hint');get('u6006-all').textContent=txt('all');openBtn.setAttribute('aria-label',txt('search'));};
let dataset=null,loading=null,sequence=0,oldFocus=null;
function recent(){try{return JSON.parse(localStorage.getItem('6006-recent-codes')||'[]').slice(0,7)}catch(e){return[]}}
function renderRecent(){results.replaceChildren();const arr=recent();if(!arr.length){results.textContent=txt('hint');return}const p=mk('p','u6006-help');p.textContent=txt('last');results.append(p);arr.forEach(x=>{if(!/^[PBCU][0-3][0-9A-F]{3}$/.test(x.code||''))return;const a=mk('a','u6006-match');a.href='/fehlercodes/?code='+encodeURIComponent(x.code);const b=mk('b');b.textContent=x.code;const s=mk('small');s.textContent=x.description||'';a.append(b,s);results.append(a)})}
function show(){oldFocus=document.activeElement;overlay.hidden=false;document.body.style.overflow='hidden';applyLabels();input.focus();renderRecent()}
overlay.addEventListener('keydown',e=>{if(e.key!=='Tab')return;const els=[...overlay.querySelectorAll('button,input,a[href]')].filter(x=>!x.hidden),first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}});
function close(){overlay.hidden=true;document.body.style.overflow='';if(oldFocus&&oldFocus.focus)oldFocus.focus()}
openBtn.onclick=show;overlay.querySelector('.u6006-close').onclick=close;overlay.addEventListener('click',e=>{if(e.target===overlay)close()});
addEventListener('keydown',e=>{if(e.key==='Escape'&&!overlay.hidden){close();return}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();show()}});
function normalize(s){return String(s||'').toLowerCase().replace(/[ıİ]/g,'i').normalize('NFD').replace(/[\u0300-\u036f]/g,'')}
async function load(){if(dataset)return dataset;if(!loading)loading=fetch('/assets/6006-dtc-catalog.json').then(r=>{if(!r.ok)throw Error(r.status);return r.json()}).then(x=>dataset=x.defs);return loading}
const synonym={direksiyon:/steer|yaw|suspension/i,lenkung:/steer|yaw|suspension/i,steering:/steer|yaw|suspension/i,sogutma:/coolant|radiator|thermostat/i,kuhlung:/coolant|radiator|thermostat/i,cooling:/coolant|radiator|thermostat/i,yag:/oil|lubrication/i,ol:/oil|lubrication/i,oil:/oil|lubrication/i,sanziman:/transmission|gear|shift|clutch/i,getriebe:/transmission|gear|shift|clutch/i,transmission:/transmission|gear|shift|clutch/i,atesleme:/misfire|ignition|spark|coil/i,zundung:/misfire|ignition|spark|coil/i,ignition:/misfire|ignition|spark|coil/i,'hava yastigi':/airbag|air bag|srs|restraint/i,airbag:/airbag|air bag|srs|restraint/i,sensor:/sensor|signal|circuit/i,sensorler:/sensor|signal|circuit/i,katalizor:/catalyst|catalytic/i,katalysator:/catalyst|catalytic/i,catalyst:/catalyst|catalytic/i,govde:/body|door|window|mirror|lamp|seat/i,karosserie:/body|door|window|mirror|lamp|seat/i,body:/body|door|window|mirror|lamp|seat/i,kraftstoff:/fuel|rail|injector/i,fuel:/fuel|rail|injector/i,bremse:/brake|abs|wheel speed/i,brake:/brake|abs|wheel speed/i,network:/communication|network|can bus/i,dpf:/particulate|soot|diesel filter|regeneration/i,adblue:/reductant|nox|scr|urea/i,egr:/exhaust gas recirculation|egr/i,yakit:/fuel|rail|injector/i,yakıt:/fuel|rail|injector/i,fren:/brake|abs|wheel speed/i,abs:/brake|abs|wheel speed/i,can:/communication|network|can bus/i,turbo:/turbo|boost|supercharg/i};
input.oninput=async()=>{
const q=input.value.trim(),token=++sequence;if(!q){renderRecent();return}
results.textContent=txt('busy');
try{const rows=await load();if(token!==sequence||overlay.hidden)return;const k=normalize(q),pat=synonym[k],arr=[];for(const row of rows){const [code,brand,description]=row;if(normalize(code+' '+brand+' '+description).includes(k)||pat?.test(description)){arr.push(row);if(arr.length>=120)break}}arr.sort((a,b)=>(a[0]===q.toUpperCase()?0:a[1]==='GENERIC'?1:2)-(b[0]===q.toUpperCase()?0:b[1]==='GENERIC'?1:2));results.replaceChildren();
const pages=[['/technik/',words[language()].tech,/technik|teknik|technical|ecu|kalibrasyon|calibration|kodlama|coding/i],['/reparatur-wartung/',words[language()].repair,/bakim|wartung|service|repair|onarim|tamir/i],['/fahrzeug/',words[language()].vehicle,/arac|fahrzeug|vehicle|marka|model/i],['/#iletisim',language()==='tr'?'İletişim':language()==='de'?'Kontakt':'Contact',/iletisim|kontakt|contact|whatsapp/i]];
for(const [url,label,pattern] of pages){if(pattern.test(k)){const a=mk('a','u6006-match');a.href=url;a.textContent=label;results.append(a)}}
if(!arr.length&&!results.children.length){results.textContent=txt('empty');return}
for(const [code,brand,desc]of arr.slice(0,7)){const a=mk('a','u6006-match');a.href='/fehlercodes/?code='+encodeURIComponent(code)+(brand==='GENERIC'?'':'&brand='+encodeURIComponent(brand));const b=mk('b');b.textContent=code;const s=mk('small');s.textContent=desc;a.append(b,s);results.append(a)}
}catch(e){if(token===sequence)results.textContent=txt('all')+': /fehlercodes/'}
};
overlay.querySelector('form').onsubmit=e=>{e.preventDefault();if(input.value.trim())location.assign('/fehlercodes/?q='+encodeURIComponent(input.value.trim()))};
if(['tech','repair','vehicle'].includes(active)){
const main=document.querySelector('main');if(main){
const section=mk('section','u6006-rail');section.setAttribute('aria-label','Sistemler');section.innerHTML='<h2>Sistemlere göz at</h2><div class="u6006-rail-inner">'+[['turbo','Turbo'],['dpf','DPF'],['adblue','SCR'],['brake','ABS'],['fuel','Yakıt'],['network','CAN']].map(([k,n])=>'<a href="/fehlercodes/?category='+k+'"><img src="/assets/realparts/'+k+'.webp" alt="" loading="lazy"/><span>'+n+'</span></a>').join('')+'</div>';
const hero=main.querySelector('.hero,.intro,.finder-section');if(hero)hero.insertAdjacentElement('afterend',section);else main.prepend(section);
}}
const railLabels={tr:['Sistemlere göz at','Yakıt'],de:['Systeme erkunden','Kraftstoff'],en:['Explore systems','Fuel']};const relabelRail=()=>{const r=document.querySelector('.u6006-rail');if(r){r.querySelector('h2').textContent=railLabels[language()][0];const a=r.querySelector('a[href*=fuel] span');if(a)a.textContent=railLabels[language()][1]}};relabelRail();
applyLabels();new MutationObserver(applyLabels).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});
})();
